<script setup>
import {ref,computed} from 'vue';import DateInput from './DateInput.vue';import {cents,inputMoney,money} from '../lib/format';
const props=defineProps({modelValue:{type:Array,default:()=>[]},total:{type:Number,default:0},date:String});const emit=defineEmits(['update:modelValue']);const count=ref(1),first=ref(props.date||'');
const sum=computed(()=>props.modelValue.reduce((s,p)=>s+(cents(p.amount)||0),0));
function generate(){const n=Math.min(240,Math.max(1,Math.trunc(Number(count.value)||1)));if(!first.value||props.total<=0)return;const [y,m,d]=first.value.split('-').map(Number);const rows=Array.from({length:n},(_,i)=>{const last=new Date(Date.UTC(y,m+i,0));const day=new Date(Date.UTC(y,m-1+i,Math.min(d,last.getUTCDate()))).toISOString().slice(0,10);return {due_date:day,amount:inputMoney(Math.floor(props.total/n)+(i<props.total%n?1:0))};});emit('update:modelValue',rows);}
</script>
<template><div class="installments-editor"><div class="form-grid three"><label>Quantidade de parcelas<input v-model.number="count" type="number" min="1" max="240"/></label><label>Primeiro vencimento<DateInput v-model="first"/></label><button type="button" class="button outline" @click="generate">Distribuir mensalmente</button></div><div class="table-scroll"><table class="editable-table"><thead><tr><th>Parcela</th><th>Vencimento</th><th>Valor (R$)</th><th></th></tr></thead><tbody><tr v-for="(p,i) in modelValue" :key="i"><td>{{i+1}}</td><td><DateInput v-model="p.due_date" required/></td><td><input v-model="p.amount" required inputmode="decimal" :aria-label="`Valor da parcela ${i+1}`"/></td><td><button type="button" class="text-button" @click="emit('update:modelValue',modelValue.filter((_,j)=>j!==i))">Remover</button></td></tr></tbody></table></div><p :class="sum===total?'positive':'negative'">Parcelas: {{money(sum)}} · valor a distribuir: {{money(total)}} · diferença: {{money(total-sum)}}</p></div></template>
